    course_description = '<h4>What You will Learn</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>You will study Information Technology topics and case studies as they apply to different Australian industries. There will be immersive hands-on practical work, using critical IT problem-solving skills, research, consultation, and collaborating with diverse teams.</p></span> </span> </div><h4>Units</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p><strong><u>Core Units</u></strong></p><ul><li>BSBCRT512 Originate and develop concepts</li><li>BSBXCS402 Promote workplace cyber security awareness and best practices</li><li>BSBXTW401 Lead and facilitate a team</li><li>ICTICT517 Match ICT needs with the strategic direction of the organisation</li><li>ICTICT532 Apply IP, ethics and privacy policies in ICT environments</li><li>ICTSAS527 Manage client problems</li></ul><p><strong><u>Elective Units</u></strong></p><ul><li>ICTCYS407 Gather, analyse and interpret threat data</li><li>ICTCYS610 Protect critical infrastructure for organisations</li><li>ICTCYS613 Utilise design methodologies for security architecture</li><li>ICTSAS524 Develop, implement and evaluate an incident response plan</li><li>ICTSAS526 Review and update disaster recovery and contingency plans</li><li>ICTNWK536 Plan, implement and test enterprise communication solutions</li><li>ICTSAS502 Establish and maintain client user liaison</li><li>ICTNWK540 Design, build and test network servers</li><li>ICTNWK546 Manage network security</li><li>ICTICT518 Research and review hardware technology options for organisations</li><li>ICTNWK556 Identify and resolve network problems</li><li>ICTICT435 Create technical documentation</li><li>ICTNWK537 Implement secure encryption technologies</li><li>ICTCLD502 Design and implement highly available cloud infrastructure</li></ul></span> </span> </div><h4>Course Structure</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li aria-level="1"><span>Total Number of Units = 20</span></li><li aria-level="1"><span>6 Core Units</span></li><li aria-level="1"><span>14 Elective Units </span></li></ul></span> </span> </div><h4>Career Opportunities</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li><span>ICT Operations Administrator,</span></li><li><span>Network E-Business Coordinator,</span></li><li><span>Network Operations Analyst,</span></li><li><span>Network Security Coordinator,</span></li><li><span>Cybersecurity Officer</span></li><li><span>Cybersecurity Consultant</span></li></ul></span> </span> </div><h4>Study Pathway</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Gain direct entry for selected Bachelor Degree course in our partnered Australian Universities.</p></span> </span> </div><h4>Mode of Delivery</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li>Face to Face( 20 hours/week).</li></ul></span> </span> </div><h4>Course Outcome</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Nationally recognised/accredited Qualification at the Diploma Level, ICT50220 Diploma of Information Technology</p></span> </span> </div>',
