    entry_requirements = '<h4>Entry Requirements</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Entry Requirements - <a href="https://mmc.edu.au/wp-content/uploads/2024/08/Entry-Requirement-Policy-and-Procedure.pdf" rel="noopener" target="_blank"><em><span>Read More</span></em></a></p></span> </span> </div> <h4>General Entry Requirements (from Prospectus)</h4> <ul> <li><strong>Age:</strong> Must be at least 18 years old.</li> <li><strong>Academic:</strong> Equivalent to an Australian Year 12 qualification.</li> <li><strong>English Test:</strong> IELTS overall 6.5, PTE 50, or equivalent. Please check course specific entry requirements for details.</li> </ul>',
