    course_description = '<h4>What You will Learn</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>You will study Information and Communications Technology topics and case studies as they apply to different Australian industries.</p><p>There will be immersive hands on practical work, using critical IT problem solving skills, research, consultation and collaborating with diverse teams.</p></span> </span> </div><h4>Units</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p><strong><u>Core Units</u></strong></p><ul><li>BSBCRT611 Apply critical thinking for complex problem solving</li><li>BSBTWK502 Manage team effectiveness</li><li>BSBXCS402 Promote workplace cyber security awareness and best practices</li><li>ICTICT608 Interact with clients on a business level</li><li>ICTICT618 Manage IP, ethics and privacy in ICT environments</li><li>ICTSAD609 Plan and monitor business analysis activities in an ICT environment</li></ul><p><strong><u>Elective Units</u></strong></p><ul><li>ICTCYS604 Implement best practices for identity management</li><li>ICTCYS606 Evaluate an organisation’s compliance with cyber security standards and law</li><li>ICTCYS608 Perform cyber security risk assessments</li><li>ICTCYS612 Design and implement virtualised cyber security infrastructure for organisations</li><li>ICTICT522 Evaluate vendor products and equipment</li><li>ICTICT617 Lead the evaluation and implementation of current industry specific technologies</li><li>ICTNWK537 Implement secure encryption technologies</li><li>ICTNWK540 Design, build and test network servers</li><li>ICTNWK546 Manage network security</li><li>ICTNWK556 Identify and resolve network problems</li></ul></span> </span> </div><h4>Course Structure</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li aria-level="1"><span>Total Number of Units = 16</span></li><li aria-level="1"><span>6 Core Units</span></li><li aria-level="1"><span>10 Elective Units </span></li