UPDATE courses SET
    course_description = '<h4>What You will Learn</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Skills as a technical specialist with knowledge in telecommunications and information technology networks using internet protocol (IP) systems.<br/>Skills to forecast network growth for enterprise network planning and to design and manage IP based network telecommunications equipment. Technical specialists to implement convergence technologies in enterprise telecommunications networks</p></span> </span> </div><h4>Units</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p><strong><u>Core Units</u></strong></p><ul><li>BSBCRT611 Apply critical thinking for complex problem solving</li><li>BSBTWK502 Manage team effectiveness</li><li>BSBXCS402 Promote workplace cyber security awareness and best practices</li><li>ICTICT608 Interact with clients on a business level</li><li>ICTICT618 Manage IP, ethics and privacy in ICT environments</li><li>ICTSAD609 Plan and monitor business analysis activities in an ICT environment</li></ul><p><strong><u>Elective Units</u></strong></p><ul><li>ICTNWK540 Design, build and test network servers</li><li>ICTICT522 Evaluate vendor products and equipment</li><li>ICTNWK546 Manage network security</li><li>ICTICT617 Lead the evaluation and implementation of current industry specific technologies</li><li>ICTNWK537 Implement secure encryption technologies</li><li>ICTNPL413 Evaluate networking regulations and legislation for the telecommunications industry</li><li>ICTNWK612 Plan and manage troubleshooting advanced integrated IP networks</li><li>ICTPMG613 Manage ICT project planning</li><li>ICTTEN615 Manage network traffic</li><li>ICTTEN622 Produce ICT network architecture designs</li></ul></span> </span> </div><h4>Course Structure</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li aria-level="1"><span>Total Number of Units = 16</span></li><li aria-level="1"><span>6 Core Units</span></li><li aria-level="1"><span>10 Elective Units </span></li></ul></span> </span> </div><h4>Mode of Delivery</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li>Face to Face( 20 hours/week).</li></ul></span> </span> </div><h4>Career Opportunities</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Job roles and titles vary across different industry sectors. Possible job titles relevant to this qualification include:</p><ul><li><ul><li>Telecommunication specialist</li><li>Telecommunications network manager</li><li>IP based optical network designer</li><li>Senior project manager</li><li>Network security manager</li></ul></li></ul></span> </span> </div>',
