    course_description = '<h4>What You will Learn</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>You will study Information and Communications Technology topics and case studies as they apply to different Australian industries.</p><p>There will be immersive hands–on practical work, using critical IT problem solving skills, research, consultation and collaborating with diverse teams.</p></span> </span> </div><h4>Units</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p><strong>Core Units</strong></p><ul><li>AURAEA002 Follow environmental and sustainability best practice in an automotive workplace</li><li>AURASA102 Follow safe working practices in an automotive workplace</li><li>AURETR112 Test and repair basic electrical circuits</li><li>AURETR123 Diagnose and repair spark ignition engine management systems</li><li>AURETR125 Test, charge and replace batteries and jump-start vehicles</li><li>AURETR129 Diagnose and repair charging systems</li><li>AURETR130 Diagnose and repair starting systems</li><li>AURETR131 Diagnose and repair ignition systems</li><li>AURLTD104 Diagnose and repair light vehicle steering systems</li><li>AURLTB103 Diagnose and repair light vehicle hydraulic braking systems</li><li>AURLTD105 Diagnose and repair light vehicle suspension systems</li><li>AURLTE102 Diagnose and repair light vehicle engines</li><li>AURLTZ101 Diagnose and repair light vehicle emission control systems</li><li>AURTTA104 Carry out servicing operations</li><li>AURTTA118 Develop and carry out diagnostic test strategies</li><li>AURTTB101 Inspect and service braking systems</li><li>AURTTC103 Diagnose and repair cooling systems</li><li>AURTTE104 Inspect and service engines</li><li>AURTTF101 Inspect and service petrol fuel systems</li><li>AURTTK102 Use and maintain tools and equipment in an automotive workplace</li></ul><p><strong><u>Elective Units</u></strong></p><ul><li>AURACA101 Respond to customer needs and enquiries in an automotive workplace</li><li>AURETR010 Repair wiring harnesses and looms</li><li>AURLTJ113 Remove, inspect and refit light vehicle wheel and tyre assemblies</li><li>AURLTQ101 Diagnose and repair light vehicle final drive assemblies</li><li>AURLTQ102 Diagnose and repair light vehicle drive shafts</li><li>AURLTX101 Diagnose and repair light vehicle manual transmissions</li><li>AURLTX102 Diagnose and repair light vehicle automatic transmissions</li><li>AURLTX103 Diagnose and repair light vehicle clutch systems</li><li>AURTTA105 Select and use bearings seals, gaskets, sealants and adhesives</li><li>AURTTB015 Assemble and fit braking system components</li><li>AURTTC001 Inspect and service cooling systems</li><li>AURTTD002 Inspect and service steering systems</li><li>AURTTD004 Inspect and service suspension systems</li><li>AURTTK001 Use and maintain measuring equipment in an automotive workplace</li><li>AURTTX102 Inspect and service manual transmissions</li><li>AURTTX103 Inspect and service automatic transmissions</li></ul></span> </span> </div><h4>Course Structure</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li aria-level="1"><span>Total Number of Units = 36</span></li><li aria-level="1"><span>20 Core Units</span></li><li aria-level="1"><span>16 Elective Units </span></li></ul></span> </span> </div><h4>Career Opportunities</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li><span>Mechanical Diagnosis</span></li><li><span>Automotive Mechanical Overhauling</span></li><li><span>Vehicle Loss</span></li><li><span>Assessing or Automotive Management</span></li></ul></span> </span> </div><h4>Study Pathway</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Certificate IV in Automotive Mechanical Diagnosis</p></span> </span> </div><h4>Mode of Delivery</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li>Face to Face and Practical (20 hours/ week).</li></ul></span> </span> </div><h4>Course Outcome</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>A nationally recognised/accredited Qualification at the Certificate III Level, AUR30620 Certificate III in Light Vehicle Mechanical Technology.</p></span> </span> </div>',
