    course_description = '<h4>What You will Learn</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>This Certificate will teach you the core knowledge and skills needed to succeed in the automotive industry including the use of light vehicle tools and specialised equipment. When you complete this course, you will be qualified for the Diploma qualifications on the way to becoming a Diagnostic Technician.</p></span> </span> </div><h4>Units</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p><strong><u>Core Units</u></strong></p><div><ul><li>AURTTA021 Diagnose complex system faults</li></ul></div><p><strong><u>Elective Units</u></strong></p><ul><li>AURETR037 Diagnose complex faults in light vehicle safety systems</li><li>AURTTR101 Diagnose complex faults in engine management systems</li><li>AURLTB104 Diagnose complex faults in light vehicle braking systems</li><li>AURLTD109 Diagnose complex faults in light vehicle steering and suspension systems</li><li>AURLTE104 Diagnose complex faults in light vehicle petrol engines</li><li>AURLTE105 Diagnose complex faults in light vehicle diesel engines systems</li><li>AURLTX104 Diagnose complex faults in light vehicle transmission and driveline systems</li><li>AURAFA103 Communicate effectively in an automotive workplace</li><li>AURTTF105 Diagnose and repair engine forced induction systems</li></ul></span> </span> </div><h4>Course Structure</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li aria-level="1"><span>Total Number of Units = 10</span></li><li aria-level="1"><span>1 Core Units</span></li><li aria-level="1"><span>9 Elective Units </span></li></ul></span> </span> </div><h4>Career Opportunities</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li><span>Motor mechanic, automotive lead or master technician</span></li><li><span>Automotive technical adviser</span></li></ul></span> </span> </div><h4>Mode of Delivery</h4><div class="uael