    course_description = '<h4>What You will Learn</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>This nationally-recognized qualification on the Diploma of Construction Management prepares you with all the foundational and practical knowledge and a hands-on career in construction management.</p></span> </span> </div><h4>Units</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p><strong><u>Core Units</u></strong></p><ul><li>BSBTWK502 Manage team effectiveness</li><li>BSBWHS521 Ensure a safe workplace for a work area</li><li>RIIENV501E Implement and maintain environmental management plans</li><li>RIIQUA501E Implement, monitor and develop quality management plans</li><li>RIIRIS501E Implement and maintain management systems to control risk</li></ul><p><strong><u>Elective Units</u></strong></p><ul><li>RIICWM501E Implement civil construction plans</li><li>BSBFIN501 Manage budgets and financial plans.</li><li>BSBPMG536 Manage project risk.</li><li>BSBSTR502 Facilitate continuous improvement</li><li>BSBOPS505 Manage organisational customer service</li><li>BSBPEF501 Manage personal and professional development</li><li>BSBOPS502 Manage business operational plans</li><li>BSBPMG537 Manage project procurement</li></ul></span> </span> </div><h4>Course Structure</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li aria-level="1"><span>Total Number of Units = 13</span></li><li aria-level="1"><span>5 Core Units</span></li><li aria-level="1"><span>8 Elective Units </span></li></ul></span> </span> </div><h4>Career Opportunities</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li><span>Project manager</span></li><li><span>Construction Manager</span></li><li><span>Site Foreman,</span></li><li><span>Estimator Senior Planner and Superintendent</span></li></ul></span> </span> </div><h4>Study Pathway</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>Advanced Diploma of Civil Construction Design.</p></span> </span> </div><h4>Mode of Delivery</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><ul><li>Face to Face( 20 hours/week).</li></ul></span> </span> </div><h4>Course Outcome</h4><div class="uael-accordion-content" role="tabpanel"> <span> <span><p>On successful completion of the course students will receive a full Certificate of Qualification for Diploma of Civil Construction Management.</p></span> </span> </div>',
